function renderStudentJourney(id){
 const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const j=studentJourneys.find(j=>j.id===id),list=chapterActivities[id]||[];
 const heading=s=>'heading-'+s.normalize('NFKC').toLowerCase().replace(/^\d+\.\s*/,'').replace(/[^\p{L}\p{N}]+/gu,'-').replace(/^-|-$/g,'');
 if(!j){const g=chapterJourneyRoutes.find(r=>r.id===id);if(!g)return '';const link=title=>'#'+e(id)+'/'+heading(title);return '<details class="student-journey"><summary>Study this chapter independently: read → example → practice → feedback → revisit</summary><p><strong>Before you start:</strong> '+e(g.ready)+'</p><p>This is the chapter pathway. For today’s smaller task, use <a href="lessons/?chapter='+e(id)+'">the allocated lesson routes</a>; do not attempt the whole chapter in one lesson.</p><ol><li><a href="'+link(g.read)+'">Read: '+e(g.read)+'</a>. Explain the main idea in your own words.</li><li><a href="'+link(g.worked)+'">Study the worked walkthrough: '+e(g.worked)+'</a>. Predict one step, then compare it with the supplied trace or explanation.</li><li><a href="'+link(g.practice)+'">Try the chapter task independently</a>. Keep your first attempt and record the evidence or test cases you used.</li><li><a href="'+link(g.practice)+'">Return to the task’s explained answer</a>. Attempt first, then open the illustrative answer or matching explanation. Compare your reasoning, not just the final value. For an issued assessment, wait until the teacher has collected it.</li><li><a href="revision/#topic-'+e(id)+'">Retrieve and revisit this topic</a>. Close the answer, change one input or scenario fact, and try again after a gap. Use only checklist items already taught.</li></ol>'+ (list.length?'<p>Extra practice: '+list.map(l=>'<a href="activities/'+e(l.pack)+'/#lesson-'+e(l.id)+'">'+e(l.title)+'</a>').join(' · ')+'.</p>':'')+'<p><a href="resources/#'+e(id)+'">Files and print copies</a> · <a href="offline/">Save an offline copy</a>.</p></details>';}
 const focused=focusedChapterLessons.filter(l=>l.chapter===id).map(l=>'<p><a class="button" href="'+e(l.path)+'">Start Week '+Math.ceil(Number(l.id.split('-l')[1])/4)+' Lesson '+((Number(l.id.split('-l')[1])-1)%4+1)+': '+e(l.title)+'</a></p>').join('');
 const activity='activities/'+j.pack+'/#lesson-'+j.activity,key='activities/'+j.pack+'/teacher.html#lesson-'+j.activity;
 return '<details class="student-journey"><summary>Study this chapter independently: read → example → practice → feedback → revisit</summary><p><strong>'+e(j.scope)+'.</strong> '+e(j.ready)+'</p>'+ focused+(id==='loops'?'<p><a href="lessons/loops/activities/">Optional loops reinforcement and extension bank</a></p>':'')+'<ol><li><a href="#'+e(id)+'/'+heading(j.read)+'">Read: '+e(j.read)+'</a>.</li><li><a href="#'+e(id)+'/'+heading(j.worked)+'">Study the worked example: '+e(j.worked)+'</a>. Predict one step before reading its result.</li><li><a href="'+activity+'">Try activity '+j.activity+': '+e(j.title)+'</a>. '+e(j.task)+'</li><li>Keep your first attempt, then <a href="'+key+'">check the matching explained answers</a>. '+e(j.feedback)+'</li><li><a href="revision/#topic-'+e(id)+'">Retrieve this topic without notes</a>. Use the chapter question first; wider syllabus checklists can include later learning. Do not tick a requirement until you can explain it independently.</li></ol><p><strong>After feedback, try a changed case:</strong> '+e(j.retry)+'</p>'+ (list.some(l=>l.pack!==j.pack||l.id!==j.activity)?'<p>More practice when ready: '+list.filter(l=>l.pack!==j.pack||l.id!==j.activity).map(l=>'<a href="activities/'+e(l.pack)+'/#lesson-'+e(l.id)+'">'+e(l.title)+'</a>').join(' · ')+'.</p>':'')+'<p><a href="resources/#'+e(id)+'">All files and print copies for this topic</a> · <a href="offline/">Save resources before going offline</a>.</p></details>';
}
